import gurobipy as gp
from gurobipy import GRB
displays = []
capacity = {}
for rec in LEGACY_RECORDS:
    if rec['source'] == 'capacity.csv':
        shelfid = rec['values']['ShelfID']
        displays.append(shelfid)
        capacity[shelfid] = float(rec['values']['Capacity'])
products = []
value = {}
weight = {}
for rec in LEGACY_RECORDS:
    if rec['source'] == 'products.csv':
        pname = rec['values']['ProductName']
        products.append(pname)
        value[pname] = float(rec['values']['Value'])
        weight[pname] = float(rec['values']['Weight'])
if len(displays) != 10:
    raise ValueError('Expected 10 displays, got %d' % len(displays))
if len(products) != 20:
    raise ValueError('Expected 20 products, got %d' % len(products))
for d in displays:
    if d not in capacity:
        raise ValueError(f'Missing capacity for display {d}')
for p in products:
    if p not in value or p not in weight:
        raise ValueError(f'Missing value or weight for product {p}')
m = gp.Model('retail_display_allocation')
x = m.addVars(displays, products, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((value[p] * x[d, p] for d in displays for p in products)), GRB.MAXIMIZE)
m.addConstrs((gp.quicksum((weight[p] * x[d, p] for p in products)) <= capacity[d] for d in displays), name='')
first_product = products[0]
m.addConstr(gp.quicksum((x[d, first_product] for d in displays)) >= 5, name='min_smartphone')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')